PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE entities (
  id          TEXT PRIMARY KEY,
  slug        TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  active      INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE categories (
  id       TEXT PRIMARY KEY,
  name_en  TEXT NOT NULL,
  name_es  TEXT NOT NULL,
  type     TEXT NOT NULL CHECK (type IN ('income','cogs','expense','transfer','equity','loan')),
  tax_line TEXT,
  sort     INTEGER NOT NULL DEFAULT 0
, active INTEGER NOT NULL DEFAULT 1, custom INTEGER NOT NULL DEFAULT 0);
CREATE TABLE accounts (
  id                    TEXT PRIMARY KEY,
  entity_id             TEXT NOT NULL REFERENCES entities(id),
  name                  TEXT NOT NULL,
  kind                  TEXT NOT NULL CHECK (kind IN ('checking','savings','credit_card','cash','loan','merchant')),
  institution           TEXT,
  last4                 TEXT,
  currency              TEXT NOT NULL DEFAULT 'USD',
  opening_balance_cents INTEGER NOT NULL DEFAULT 0,
  opening_date          TEXT,
  active                INTEGER NOT NULL DEFAULT 1
, provider_account_id TEXT, opening_source TEXT);
CREATE TABLE import_batches (
  id              TEXT PRIMARY KEY,
  account_id      TEXT NOT NULL REFERENCES accounts(id),
  filename        TEXT,
  preset          TEXT NOT NULL,
  row_count       INTEGER NOT NULL DEFAULT 0,
  imported_count  INTEGER NOT NULL DEFAULT 0,
  duplicate_count INTEGER NOT NULL DEFAULT 0,
  file_hash       TEXT,
  imported_by     TEXT,
  imported_at     TEXT NOT NULL
);
CREATE TABLE bills (
  id           TEXT PRIMARY KEY,
  entity_id    TEXT NOT NULL REFERENCES entities(id),
  vendor       TEXT NOT NULL,
  description  TEXT,
  amount_cents INTEGER NOT NULL,
  due_date     TEXT,
  recurring    TEXT NOT NULL DEFAULT 'none' CHECK (recurring IN ('none','monthly','quarterly','annual')),
  status       TEXT NOT NULL DEFAULT 'unpaid' CHECK (status IN ('unpaid','paid','void')),
  paid_txn_id  TEXT REFERENCES transactions(id),
  created_by   TEXT,
  created_at   TEXT NOT NULL
);
CREATE TABLE invoices (
  id           TEXT PRIMARY KEY,
  entity_id    TEXT NOT NULL REFERENCES entities(id),
  client       TEXT NOT NULL,
  description  TEXT,
  amount_cents INTEGER NOT NULL,
  issue_date   TEXT,
  due_date     TEXT,
  status       TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','paid','overdue','void')),
  paid_txn_id  TEXT REFERENCES transactions(id),
  created_by   TEXT,
  created_at   TEXT NOT NULL
);
CREATE TABLE reconciliations (
  id                      TEXT PRIMARY KEY,
  account_id              TEXT NOT NULL REFERENCES accounts(id),
  period                  TEXT NOT NULL,               
  statement_date          TEXT,
  statement_balance_cents INTEGER NOT NULL DEFAULT 0,
  computed_balance_cents  INTEGER NOT NULL DEFAULT 0,
  difference_cents        INTEGER NOT NULL DEFAULT 0,
  status                  TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','balanced','closed')),
  notes                   TEXT,
  closed_by               TEXT,
  closed_at               TEXT
, statement_doc TEXT);
CREATE TABLE users (
  id              TEXT PRIMARY KEY,
  username        TEXT NOT NULL UNIQUE,
  display_name    TEXT NOT NULL,
  email           TEXT,
  role            TEXT NOT NULL CHECK (role IN ('owner','partner')),
  lang            TEXT NOT NULL DEFAULT 'en',
  pin_hash        TEXT,
  pin_salt        TEXT,
  must_change_pin INTEGER NOT NULL DEFAULT 1,
  active          INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL
);
CREATE TABLE sessions (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id),
  token_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked    INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE permissions (
  user_id TEXT NOT NULL REFERENCES users(id),
  module  TEXT NOT NULL CHECK (module IN ('dashboard','transactions','import','reconcile','bills','invoices','reports','documents','admin')),
  level   TEXT NOT NULL CHECK (level IN ('none','read','write')),
  PRIMARY KEY (user_id, module)
);
CREATE TABLE user_entities (
  user_id   TEXT NOT NULL REFERENCES users(id),
  entity_id TEXT NOT NULL REFERENCES entities(id),
  PRIMARY KEY (user_id, entity_id)
);
CREATE TABLE audit_log (
  id          TEXT PRIMARY KEY,
  user_id     TEXT,
  action      TEXT NOT NULL,
  module      TEXT,
  detail_json TEXT,
  ts          TEXT NOT NULL
);
CREATE TABLE login_attempts (
  id       TEXT PRIMARY KEY,
  username TEXT NOT NULL,
  ts       TEXT NOT NULL
, ip TEXT);
CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL DEFAULT ''
);
CREATE TABLE sync_items (
  id                 TEXT PRIMARY KEY,
  provider           TEXT NOT NULL,
  item_id            TEXT NOT NULL,
  cursor             TEXT,
  consent_expires_at TEXT,
  last_sync_at       TEXT,
  status             TEXT,
  last_error         TEXT
);
CREATE TABLE IF NOT EXISTS "transactions" (
  id                     TEXT PRIMARY KEY,
  entity_id              TEXT NOT NULL REFERENCES entities(id),
  account_id             TEXT NOT NULL REFERENCES accounts(id),
  
  
  
  
  
  txn_date               TEXT NOT NULL CHECK (txn_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  description            TEXT NOT NULL,
  amount_cents           INTEGER NOT NULL,
  currency               TEXT NOT NULL DEFAULT 'USD',
  category_id            TEXT REFERENCES categories(id),
  counterparty_entity_id TEXT REFERENCES entities(id),
  notes                  TEXT,
  reference_id           TEXT,
  import_batch_id        TEXT,
  
  source                 TEXT NOT NULL CHECK (source IN ('csv','manual','email','aggregator')),
  source_provider        TEXT,
  
  
  
  
  
  pending                INTEGER NOT NULL DEFAULT 0,
  
  
  pending_reference_id   TEXT,
  
  
  
  
  removed_at             TEXT,
  
  
  raw                    TEXT,
  cleared                INTEGER NOT NULL DEFAULT 0,
  reconciliation_id      TEXT,
  created_by             TEXT,
  created_at             TEXT NOT NULL
, needs_review INTEGER NOT NULL DEFAULT 0, review_reason TEXT);
CREATE TABLE IF NOT EXISTS "import_previews" (
  id         TEXT PRIMARY KEY,
  
  user_id    TEXT NOT NULL,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  entity_id  TEXT NOT NULL REFERENCES entities(id),
  preset     TEXT NOT NULL,
  filename   TEXT,
  file_hash  TEXT,
  rows_json  TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE review_dismissals (
  id             TEXT PRIMARY KEY,

  
  
  
  
  
  
  
  transaction_id TEXT NOT NULL REFERENCES transactions(id),

  
  
  
  
  
  
  
  
  
  
  
  
  kind           TEXT NOT NULL CHECK (kind IN ('anomaly', 'flag')),
  reason         TEXT,
  dismissed_by   TEXT,
  dismissed_at   TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "vendor_rules" (
  id            TEXT PRIMARY KEY,

  
  
  
  
  match_text    TEXT NOT NULL UNIQUE
                CHECK (length(match_text) >= 3 AND match_text = upper(match_text)),

  category_id   TEXT NOT NULL REFERENCES categories(id),
  entity_id     TEXT REFERENCES entities(id),
  priority      INTEGER NOT NULL DEFAULT 100,
  active        INTEGER NOT NULL DEFAULT 1,
  created_by    TEXT,
  created_at    TEXT NOT NULL,
  applied_count INTEGER NOT NULL DEFAULT 0
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_categories_type_sort ON categories(type, sort);
CREATE INDEX idx_accounts_entity ON accounts(entity_id);
CREATE INDEX idx_import_batches_account ON import_batches(account_id, imported_at);
CREATE INDEX idx_bills_entity_status ON bills(entity_id, status, due_date);
CREATE INDEX idx_invoices_entity_status ON invoices(entity_id, status, due_date);
CREATE UNIQUE INDEX idx_recon_account_period ON reconciliations(account_id, period);
CREATE INDEX idx_sessions_user ON sessions(user_id, revoked);
CREATE INDEX idx_audit_ts ON audit_log(ts);
CREATE INDEX idx_audit_user ON audit_log(user_id, ts);
CREATE INDEX idx_login_attempts ON login_attempts(username, ts);
CREATE INDEX idx_login_attempts_user_ip ON login_attempts(username, ip, ts);
CREATE UNIQUE INDEX idx_sync_items_provider_item ON sync_items(provider, item_id);
CREATE UNIQUE INDEX idx_txn_account_reference
  ON transactions(account_id, reference_id)
  WHERE reference_id IS NOT NULL;
CREATE INDEX idx_txn_entity_date  ON transactions(entity_id, txn_date);
CREATE INDEX idx_txn_account_date ON transactions(account_id, txn_date);
CREATE INDEX idx_txn_category     ON transactions(category_id);
CREATE INDEX idx_txn_dupe_probe   ON transactions(account_id, txn_date, amount_cents);
CREATE INDEX idx_txn_recon        ON transactions(reconciliation_id);
CREATE INDEX idx_txn_counterparty ON transactions(counterparty_entity_id);
CREATE INDEX idx_txn_batch        ON transactions(import_batch_id);
CREATE INDEX idx_txn_removed      ON transactions(removed_at);
CREATE INDEX idx_import_previews_created ON import_previews(created_at);
CREATE INDEX idx_categories_active ON categories(active);
CREATE UNIQUE INDEX idx_review_dismissals_txn_kind ON review_dismissals(transaction_id, kind);
CREATE INDEX idx_transactions_needs_review ON transactions(needs_review) WHERE needs_review = 1;
CREATE INDEX idx_vendor_rules_apply ON vendor_rules(active, priority);
